player = {
  x=8, y=112,
  vx=0, vy=0,
  spr=1,
  suelo=false,
  saltos=1,
  coins=0,
  key=false,
  map_offset=0
}

gravity = 0.2
jump_speed = -3
trampoline_boost_3 = -math.sqrt(2 * gravity * 24)
trampoline_boost_7 = -math.sqrt(2 * gravity * 56)

function is_solid(x,y)
  local tile = mget((x//8)+player.map_offset, y//8)
  return tile == 2 or tile == 3 or tile == 10 or tile == 19 or tile == 20 or tile == 21
end

function trampoline_type(x,y)
  local tile = mget((x//8)+player.map_offset, y//8)
  if tile == 5 then return "small" end
  if tile == 6 then return "big" end
  return nil
end

function is_spike(x,y)
  local tile = mget((x//8)+player.map_offset, y//8)
  return tile == 4
end

function is_coin(x,y)
  local tile = mget((x//8)+player.map_offset, y//8)
  return tile == 7
end

function is_button(x,y)
  local tile = mget((x//8)+player.map_offset, y//8)
  return tile == 8
end

function is_key(x,y)
  local tile = mget((x//8)+player.map_offset, y//8)
  return tile == 11
end

function is_door(x,y)
  local tile = mget((x//8)+player.map_offset, y//8)
  return tile == 15
end

function is_conveyor(x,y)
  local tile = mget((x//8)+player.map_offset, y//8)
  return tile == 19 or tile == 20 or tile == 21
end

function collide(x,y)
  return is_solid(x, y) or
         is_solid(x+7, y) or
         is_solid(x, y+7) or
         is_solid(x+7, y+7)
end

function update_player()
  player.vx = 0
  if btn(2) then player.vx = -1 end
  if btn(3) then player.vx = 1 end

  player.vy = player.vy + gravity

  local new_x = player.x + player.vx
  if not collide(new_x, player.y) then
    player.x = new_x
  end

  local new_y = player.y + player.vy
  if player.vy > 0 then
    if not collide(player.x, new_y) then
      player.y = new_y
      player.suelo = false
    else
      player.y = (new_y//8)*8
      player.vy = 0
      player.suelo = true
      player.saltos = 1
    end
    local tramp = trampoline_type(player.x, player.y+8)
    if tramp == "small" then
      player.vy = trampoline_boost_3
      player.suelo = false
    elseif tramp == "big" then
      player.vy = trampoline_boost_7
      player.suelo = false
    end
  elseif player.vy < 0 then
    if not collide(player.x, new_y) then
      player.y = new_y
    else
      player.vy = 0
    end
  end

  if btnp(4) and player.saltos > 0 then
    player.vy = jump_speed
    player.saltos = player.saltos - 1
    player.suelo = false
  end

  if is_spike(player.x, player.y) or
     is_spike(player.x+7, player.y) or
     is_spike(player.x, player.y+7) or
     is_spike(player.x+7, player.y+7) then
    player.x = 8
    player.y = 112
    player.vx = 0
    player.vy = 0
  end

  if is_coin(player.x, player.y) then
    mset((player.x//8)+player.map_offset, player.y//8, 0)
    player.coins = player.coins + 1
  end
  if is_coin(player.x+7, player.y) then
    mset(((player.x+7)//8)+player.map_offset, player.y//8, 0)
    player.coins = player.coins + 1
  end
  if is_coin(player.x, player.y+7) then
    mset((player.x//8)+player.map_offset, (player.y+7)//8, 0)
    player.coins = player.coins + 1
  end
  if is_coin(player.x+7, player.y+7) then
    mset(((player.x+7)//8)+player.map_offset, ((player.y+7)//8), 0)
    player.coins = player.coins + 1
  end

  if is_button(player.x, player.y+8) then
    mset((player.x//8)+player.map_offset, (player.y+8)//8, 9)
    for tx=0,29 do
      for ty=0,16 do
        if mget(tx+player.map_offset,ty) == 10 then
          mset(tx+player.map_offset,ty,0)
        end
      end
    end
  end

  if is_key(player.x, player.y) or
     is_key(player.x+7, player.y) or
     is_key(player.x, player.y+7) or
     is_key(player.x+7, player.y+7) then
    mset((player.x//8)+player.map_offset, player.y//8, 0)
    player.key = true
    for tx=0,29 do
      for ty=0,16 do
        if mget(tx+player.map_offset,ty) == 16 then
          mset(tx+player.map_offset,ty,15)
          mset(tx+1+player.map_offset,ty,17)
        end
      end
    end
  end

  if is_door(player.x, player.y) or
     is_door(player.x+7, player.y) or
     is_door(player.x, player.y+7) or
     is_door(player.x+7, player.y+7) then
    if btnp(0) then
      player.map_offset = player.map_offset + 30
      player.x = 8
      player.y = 112
    end
  end

  -- cintas transportadoras: sprites 19,20,21
  if is_conveyor(player.x, player.y+8) then
    player.x = player.x + 1
  end
end

function draw_player()
  spr(player.spr, player.x, player.y, 0)
  print("Coins: "..player.coins, 2, 2, 12)
end

function TIC()
  cls()
  map(player.map_offset,0,30,17,0,0,0)
  update_player()
  draw_player()
end
